display.code:
.container {
  display: flex;
  justify-content: center;
}

.hidden {
  display: none;
}

margin.code:
/* Todas direcciones */
margin: 20px;
/* Vertical | Horizontal */
margin: 10px 20px;
/* Centrado */
margin: 0 auto;

flex.code:
.item {
  flex: 1; /* Ocupa todo el espacio posible */
}
.fixed {
  flex: 0 0 200px; /* Ancho fijo de 200px */
}

align-items.code:
.container {
  display: flex;
  align-items: center; /* Centrado vertical */
  height: 100vh;
}

const.code:
const user = { name: 'Fran' };
user.name = 'Frank'; // Válido (mutación)
// user = {}; // Error (reasignación)

map.code:
const nums = [1, 2, 3];
const squares = nums.map(x => x * x);
// [1, 4, 9]

filter.code:
const nums = [1, 2, 3, 4];
const evens = nums.filter(n => n % 2 === 0);
// [2, 4]

destructuring.code:
const user = { id: 1, info: { name: 'F' } };
const { info: { name } } = user;
console.log(name); // 'F'

promise.code:
const miPromesa = new Promise((resolve, reject) => {
  setTimeout(() => resolve('Hecho!'), 1000);
});

await.code:
async function main() {
  const data = await fetch('/api');
  console.log(data);
}
